/* /events/ — the weekly events page (generated by scripts/build-events-page.js).
   It reads ../events.json at runtime; tests serve a fixed feed (see
   helpers/atlas.js) because the real one is regenerated weekly and not in git. */
const { test, expect, DATA, byId, eventsFixture } = require("./helpers/atlas");

test("the events page loads and lists upcoming events", async ({ page }) => {
  const feed = eventsFixture();
  await page.goto("./events/");
  await expect(page.locator("#list .ev")).toHaveCount(feed.events.length);
  await expect(page.locator("#genLine")).toContainText("refreshed");
  await expect(page.locator("#list")).toContainText(feed.events[0].title);
});

test("an event's \"on the atlas\" link opens that organization's drawer", async ({ page }) => {
  const hosted = eventsFixture().events.find(e => e.atlasId);
  await page.goto("./events/");
  await page.locator("#list a.atlas").first().click();
  await expect(page.locator("#drawer")).toHaveClass(/\bopen\b/);
  await expect(page.locator("#drName")).toHaveText(byId[hosted.atlasId].name);
});

test.describe("without events.json", () => {
  // the weekly feed can be missing (first deploy, a failed refresh); the page
  // must say so instead of hanging on "Loading events…" or throwing
  test.use({ eventsFeed: "missing", expectedHttpErrors: [/\/events\.json/] });

  test("the events page shows a fallback message and no errors", async ({ page }) => {
    await page.goto("./events/");
    await expect(page.locator("#list .empty")).toBeVisible();
    await expect(page.locator("#list")).not.toContainText("Loading events");
  });
});

// Contract 2 on the events page: its footer count comes from the data too.
// The events page ships no script, so any count lifted into its footer could only
// go stale — it read "101 organizations" for months. The clause is dropped at build
// time instead (scripts/build-events-page.js); the atlas page still shows a live
// count. This guards the drop, so a number cannot quietly return.
test("the events page footer claims no organization count", async ({ page }) => {
  await page.goto("./events/");
  await expect(page.locator("#footCount")).toHaveCount(0);
  await expect(page.locator("footer")).not.toHaveText(/\d[\d,]*\s+organi[sz]ations/i);
});

// Same for the curation month, and for the same reason: this page has no script, so
// a date lifted into it can only rot. It read "Curated June 2026" into October.
test("the events page footer claims no curation date", async ({ page }) => {
  await page.goto("./events/");
  await expect(page.locator("#footCurated")).toHaveCount(0);
  await expect(page.locator("footer")).not.toHaveText(/Curated/i);
});
